#!/usr/bin/env node
import { readFile } from 'node:fs/promises'

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

const commands = {
  async parallel(arg) {
    const n = Math.max(0, Number.parseInt(arg ?? '0', 10) || 0)
    let active = 0
    let peak = 0
    const runTask = async () => {
      active += 1
      if (active > peak) peak = active
      try {
        await sleep(50)
      } finally {
        active -= 1
      }
    }
    // 互不依赖的任务一次性全部启动，重叠执行
    await Promise.all(Array.from({ length: n }, runTask))
    return `maxConcurrent=${peak}`
  },

  async dedupe(arg) {
    const value = arg
    let loads = 0
    const cache = new Map()
    const load = (key) => {
      if (!cache.has(key)) {
        loads += 1
        cache.set(key, Promise.resolve(value))
      }
      return cache.get(key)
    }
    const key = 'item'
    await load(key)
    const second = await load(key)
    return `loads=${loads} value=${second}`
  },

  async topn(path) {
    let text
    try {
      text = await readFile(path, 'utf8')
    } catch {
      return null
    }
    const input = JSON.parse(text)
    const before = JSON.stringify(input)
    const top = input.slice().sort((a, b) => b - a).slice(0, 3)
    const mutated = JSON.stringify(input) !== before
    return `top=${top.join(',')} mutated=${mutated}`
  },
}

const [name, ...rest] = process.argv.slice(2)
const handler = Object.prototype.hasOwnProperty.call(commands, name) ? commands[name] : null

if (!handler) {
  console.log('error=unknown-command')
  process.exitCode = 1
} else {
  const output = await handler(rest[0])
  if (output === null) {
    console.log('error=missing-input')
    process.exitCode = 1
  } else {
    console.log(output)
  }
}
